import sys

def solve():
    import sys
    import numpy as np

    def read_input():
        import sys
        input = sys.stdin.read().split()
        n = int(input[0])
        m = int(input[1])
        board = [list(input[i + 2]) for i in range(n)]
        return n, m, board

    def is_valid_tiling(n, m, board):
        def check_color(i, j):
            if i % 2 == j % 2:
                return 'w'
            else:
                return 'b'

        for i in range(n):
            for j in range(m):
                if board[i][j] != '.' and board[i][j] != check_color(i, j):
                    return False
        return True

    def tile_board(n, m, board):
        def place_trimino(i, j, symbol):
            board[i][j] = symbol
            board[i][j + 1] = symbol
            board[i][j + 2] = symbol

        symbols = ['a', 'b', 'c', 'd']
        symbol_index = 0

        for i in range(0, n, 3):
            for j in range(0, m, 3):
                if board[i][j] == '.':
                    continue
                if j + 2 < m and board[i][j] == board[i][j + 1] == board[i][j + 2]:
                    place_trimino(i, j, symbols[symbol_index])
                    symbol_index = (symbol_index + 1) % 4
                elif i + 2 < n and board[i][j] == board[i + 1][j] == board[i + 2][j]:
                    for k in range(3):
                        board[i + k][j] = symbols[symbol_index]
                    symbol_index = (symbol_index + 1) % 4
        return board

    def can_tile(n, m, board):
        if n % 3 != 0 and m % 3 != 0:
            return False
        if not is_valid_tiling(n, m, board):
            return False
        return True

    n, m, board = read_input()

    if not can_tile(n, m, board):
        print("NO")
        return

    tiling = tile_board(n, m, board)

    print("YES")
    for row in tiling:
        print(''.join(row))

